{
  "implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    raw_edges = case['distances']
    # Canonicalize and compute mutual reachability
    edge_list = []
    seen = set()
    for a, b, d in raw_edges:
        if a == b:
            continue
        # canonical order
        if a < b:
            n1, n2 = a, b
        else:
            n1, n2 = b, a
        if (n1, n2) in seen:
            continue
        seen.add((n1, n2))
        w = max(core[n1], core[n2], d)
        edge_list.append((w, n1, n2))
    # Sort by weight then endpoints
    edge_list.sort(key=lambda x: (x[0], x[1], x[2]))
    # Union-Find
    parent = {n: n for n in nodes}
    rank = {n: 0 for n in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst_edges = []
    total = 0.0
    for w, n1, n2 in edge_list:
        if union(n1, n2):
            mst_edges.append([n1, n2, w])
            total += w
            if len(mst_edges) == len(nodes) - 1:
                break
    # Final sort of MST edges (should already be sorted, but ensure)
    mst_edges.sort(key=lambda e: (e[2], e[0], e[1]))
    return {'mst_edges': mst_edges, 'total_weight': total}"
}
